function validate([root, k]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null || root[0] === undefined) return 'root needs at least one node.';
  // Read the level-order array the way it is built: every node takes the next two slots as its children.
  const queue = [0];
  const kids = new Map();
  let next = 1;
  for (let head = 0; head < queue.length; head++) {
    const at = queue[head];
    const value = root[at];
    if (typeof value === 'number') {
      if (!Number.isInteger(value) || value < 1 || value > 10000) return 'An internal node is written as its len, an integer from 1 to 10^4.';
    } else if (typeof value !== 'string' || !/^[a-z]{1,50}$/.test(value)) {
      return 'A leaf is written as its val: 1 to 50 lowercase letters.';
    }
    const pair = [];
    for (let side = 0; side < 2; side++) {
      if (next < root.length && root[next] !== null) {
        queue.push(next);
        pair.push(next);
      } else {
        pair.push(-1);
      }
      next++;
    }
    kids.set(at, pair);
    if (queue.length > 1000) return 'The tree has at most 1000 nodes.';
  }
  if (root.slice(next).some(value => value !== null)) return 'root has values that are not attached to the tree.';
  const length = new Map();
  for (let head = queue.length - 1; head >= 0; head--) {
    const at = queue[head];
    const value = root[at];
    const [left, right] = kids.get(at);
    if (typeof value === 'string') {
      if (left !== -1 || right !== -1) return 'A leaf (a string) cannot have children.';
      length.set(at, value.length);
      continue;
    }
    if (left === -1 && right === -1) return 'An internal node (a number) needs at least one child.';
    const total = (left === -1 ? 0 : length.get(left)) + (right === -1 ? 0 : length.get(right));
    if (total !== value) return `An internal node's len must equal the length of its string (${total}, not ${value}).`;
    length.set(at, total);
  }
  if (!Number.isInteger(k) || k < 1 || k > length.get(0)) return `k must be between 1 and ${length.get(0)}.`;
  return null;
}

