function adapt(input, solve, kit) {
  class RopeTreeNode {
    constructor(len = 0, val = '', left = null, right = null) {
      this.len = len;
      this.val = val;
      this.left = left;
      this.right = right;
    }
  }
  // A number in the array is an internal node's len; a string is a leaf's val.
  const make = value => typeof value === 'number' ? new RopeTreeNode(value, '') : new RopeTreeNode(0, value);
  const [values, k] = input;
  const root = make(values[0]);
  const queue = [root];
  let next = 1;
  for (let head = 0; head < queue.length && next < values.length; head++) {
    for (const side of ['left', 'right']) {
      if (next < values.length && values[next] !== null) {
        queue[head][side] = make(values[next]);
        queue.push(queue[head][side]);
      }
      next++;
    }
  }
  const result = solve(root, k);
  if (typeof result !== 'string' || result.length !== 1) throw new Error('Return a single character as a string.');
  return result;
}

