function getKthCharacter(root, k) {
  if (root.len === 0) {
    return root.val[k - 1];
  }
  const left = root.left;
  let leftLength = 0;
  if (left !== null) {
    leftLength = left.len === 0 ? left.val.length : left.len;
  }
  if (k <= leftLength) {
    return getKthCharacter(left, k);
  }
  return getKthCharacter(root.right, k - leftLength);
}

