function getKthCharacter(root, k) {
  // Spell out the whole string from the leaves, left to right, then index it.
  const parts = [];
  const stack = [root];
  while (stack.length > 0) {
    const node = stack.pop();
    if (node === null) continue;
    if (node.left === null && node.right === null) parts.push(node.val);
    else stack.push(node.right, node.left);
  }
  return parts.join('').charAt(k - 1);
}

