function generate(rand, size) {
  const large = size === 'large';
  const pick = n => Math.floor(rand() * n);
  const word = () => {
    let text = '';
    const length = 1 + pick(large ? 20 : 4);
    for (let i = 0; i < length; i++) text += String.fromCharCode(97 + pick(26));
    return text;
  };
  for (;;) {
    let nodes = 0;
    // Split the leaves between two subtrees, or now and then hang a single child under an internal node.
    const build = leaves => {
      nodes++;
      if (leaves === 1 && rand() < (large ? 0.85 : 0.65)) {
        const val = word();
        return { len: 0, val, left: null, right: null, size: val.length };
      }
      const node = { len: 0, val: '', left: null, right: null, size: 0 };
      if (leaves > 1 && rand() >= 0.12) {
        const split = 1 + pick(leaves - 1);
        node.left = build(split);
        node.right = build(leaves - split);
      } else if (rand() < 0.5) {
        node.left = build(leaves);
      } else {
        node.right = build(leaves);
      }
      node.size = (node.left ? node.left.size : 0) + (node.right ? node.right.size : 0);
      node.len = node.size;
      return node;
    };
    const root = build(large ? 380 + pick(50) : 1 + pick(5));
    if (nodes > 1000 || root.size > 10000) continue;
    const values = [];
    const queue = [root];
    for (let head = 0; head < queue.length; head++) {
      const node = queue[head];
      if (node === null) {
        values.push(null);
        continue;
      }
      values.push(node.len > 0 ? node.len : node.val);
      queue.push(node.left, node.right);
    }
    while (values[values.length - 1] === null) values.pop();
    return [values, 1 + pick(root.size)];
  }
}
